          {
            "type": "html",
            "html": "<p>2026 年 5 月 22 日晚上，上海虹桥。</p>",
            "text": "2026 年 5 月 22 日晚上，上海虹桥。"
          },
          {
            "type": "html",
            "html": "<p>第二天要开一场三百人规模的大会。政府相关领导会来，Steve Hoffman 要做两场主旨演讲，台下坐着企业家、投资人和科创专家。</p>",
            "text": "第二天要开一场三百人规模的大会。政府相关领导会来，Steve Hoffman 要做两场主旨演讲，台下坐着企业家、投资人和科创专家。"
          },
          {
            "type": "html",
            "html": "<p>而负责把这场大会做出来的公司，当时只有 3 个人。</p>",
            "text": "而负责把这场大会做出来的公司，当时只有 3 个人。"
          },
          {
            "type": "html",
            "html": "<p>从活动策划、主视觉、邀请函、报名系统，到现场音乐和每一页演示文稿，没有一件事是完整交给外部团队的，也没有一件事是由 3 个人从头到尾亲手完成的。我们把任务拆开，交给一组 AI Agent。人负责说清楚要什么、判断结果、作出取舍；Agent 负责把东西做出来，再根据反馈修改。</p>",
            "text": "从活动策划、主视觉、邀请函、报名系统，到现场音乐和每一页演示文稿，没有一件事是完整交给外部团队的，也没有一件事是由 3 个人从头到尾亲手完成的。我们把任务拆开，交给一组 AI Agent。人负责说清楚要什么、判断结果、作出取舍；Agent 负责把东西做出来，再根据反馈修改。"
          },
          {
            "type": "html",
            "html": "<p>那天晚上是彩排。Agent 还在调试 PPT，生成暖场音乐，调整第二天的发言稿，整理最终的参会名单。流程仍然紧张，但现场少了一种我过去很熟悉的忙碌：人不断进出房间，围着电脑修改文件，等某个同事把上一环交付过来。</p>",
            "text": "那天晚上是彩排。Agent 还在调试 PPT，生成暖场音乐，调整第二天的发言稿，整理最终的参会名单。流程仍然紧张，但现场少了一种我过去很熟悉的忙碌：人不断进出房间，围着电脑修改文件，等某个同事把上一环交付过来。"
          },
          {
            "type": "html",
            "html": "<p>我第一次非常具体地意识到，几个月前做的那个决定，真的可以走通：用 AI 原生的方式，重新做一家公司。</p>",
            "text": "我第一次非常具体地意识到，几个月前做的那个决定，真的可以走通：用 AI 原生的方式，重新做一家公司。"
          },
          {
            "type": "html",
            "html": "<p class=\"pullquote\"><strong>我们的市场部，0 个人类员工。</strong></p>",
            "text": "我们的市场部，0 个人类员工。"
          },
          {
            "type": "html",
            "html": "<p>过去我做市场，习惯先想岗位：内容要一个人，设计要一个人，投放要一个人，数据要一个人，再找一个人把他们协调起来。每年开预算会，接到增长目标，第一反应往往是加人。要做更多结果，就要更多的人，再拿更多的人去要更多预算。</p>",
            "text": "过去我做市场，习惯先想岗位：内容要一个人，设计要一个人，投放要一个人，数据要一个人，再找一个人把他们协调起来。每年开预算会，接到增长目标，第一反应往往是加人。要做更多结果，就要更多的人，再拿更多的人去要更多预算。"
          },
          {
            "type": "html",
            "html": "<p>但这一次，我没有招聘一个市场部员工。这个变化不只是因为节省成本，而是因为当我重新问自己“这件事到底需要谁”时，答案已经变了。</p>",
            "text": "但这一次，我没有招聘一个市场部员工。这个变化不只是因为节省成本，而是因为当我重新问自己“这件事到底需要谁”时，答案已经变了。"
          },
          {
            "type": "html",
            "html": "<p>而改变的，也不只是一个市场部。</p>",
            "text": "而改变的，也不只是一个市场部。"
          },
          {
            "type": "html",
            "html": "<h2>百年管理学的危机</h2>",
            "text": "百年管理学的危机"
          },
          {
            "type": "html",
            "html": "<p>管理学研究了上百年的人如何管理人。怎么设岗，怎么招人，怎么分工，怎么协调，怎么激励，怎么考核，几乎所有组织管理的方法，都建立在一个共同前提之上：组织由人构成，工作由人完成。</p>",
            "text": "管理学研究了上百年的人如何管理人。怎么设岗，怎么招人，怎么分工，怎么协调，怎么激励，怎么考核，几乎所有组织管理的方法，都建立在一个共同前提之上：组织由人构成，工作由人完成。"
          },
          {
            "type": "html",
            "html": "<p>AI Agent 正在成为办公室里的一个新物种。它可以理解语言、调用工具、完成工作流，也可以在一定范围内进行判断。Elon Musk 曾在访谈中谈到，凡是在电脑屏幕上完成的工作，都可能很快受到 AI 的深刻影响。这个判断听上去激进，但在我们的公司，已经有超过一半的市场与运营工作由 Agent 参与完成。</p>",
            "text": "AI Agent 正在成为办公室里的一个新物种。它可以理解语言、调用工具、完成工作流，也可以在一定范围内进行判断。Elon Musk 曾在访谈中谈到，凡是在电脑屏幕上完成的工作，都可能很快受到 AI 的深刻影响。这个判断听上去激进，但在我们的公司，已经有超过一半的市场与运营工作由 Agent 参与完成。"
          },
          {
            "type": "html",
            "html": "<p>Agent 消耗的是 Token，不会因为累了就把工作推到明天。昨天确认过的做法可以留下来，让它今天接着用。但只要输入、工具或规则变了，同一个任务就可能做出不同的结果。随时待命和交付可靠，是两回事。</p>",
            "text": "Agent 消耗的是 Token，不会因为累了就把工作推到明天。昨天确认过的做法可以留下来，让它今天接着用。但只要输入、工具或规则变了，同一个任务就可能做出不同的结果。随时待命和交付可靠，是两回事。"
          },
          {
            "type": "html",
            "html": "<p>但这并不意味着管理消失了。管理的问题只是换了一个对象，也换了一种形态。</p>",
            "text": "但这并不意味着管理消失了。管理的问题只是换了一个对象，也换了一种形态。"
          },
          {
            "type": "html",
            "html": "<p>我们需要培训 Agent，让它理解工作的上下文；需要设计权限，决定它可以看到什么、调用什么、执行什么；需要建立反馈机制，在它犯错时及时纠正。有时还需要让一个 Agent 监督另一个 Agent，或让不同的 Agent 交叉验证结果。涉及客户、财务、合规和重大决策的工作，在目前阶段仍然需要人审核，以免一个看似合理的错误带来不可预知的后果。</p>",
            "text": "我们需要培训 Agent，让它理解工作的上下文；需要设计权限，决定它可以看到什么、调用什么、执行什么；需要建立反馈机制，在它犯错时及时纠正。有时还需要让一个 Agent 监督另一个 Agent，或让不同的 Agent 交叉验证结果。涉及客户、财务、合规和重大决策的工作，在目前阶段仍然需要人审核，以免一个看似合理的错误带来不可预知的后果。"
          },
          {
            "type": "html",
            "html": "<p>过去的管理，重点是管理人的时间、任务和行为。AI 时代的管理，还要管理上下文、权限、工作流、反馈和责任边界。</p>",
            "text": "过去的管理，重点是管理人的时间、任务和行为。AI 时代的管理，还要管理上下文、权限、工作流、反馈和责任边界。"
          },
          {
            "type": "html",
            "html": "<p>所以，管理学并没有消失，但它一定需要变革。</p>",
            "text": "所以，管理学并没有消失，但它一定需要变革。"
          },
          {
            "type": "html",
            "html": "<h2>从 GPT 到 ChatGPT：技术怎样真正进入人的工作</h2>",
            "text": "从 GPT 到 ChatGPT：技术怎样真正进入人的工作"
          },
          {
            "type": "html",
            "html": "<p>我和 AI 的关系，不是从 ChatGPT 开始的。</p>",
            "text": "我和 AI 的关系，不是从 ChatGPT 开始的。"
          },
          {
            "type": "html",
            "html": "<p>在 ChatGPT 出现以前，我在 MIT 的 AI 产品设计课程里接触到了 GPT-1、GPT-2 这些早期的大语言模型。从今天的眼光看，那时的产品还很稚嫩，缺少适合普通用户的界面，主要在技术圈受到关注。但它们表现出来的语言能力，已经足够让人震撼：机器似乎不再只是按照人写好的规则处理信息，而是开始表现出理解和生成语言的能力。</p>",
            "text": "在 ChatGPT 出现以前，我在 MIT 的 AI 产品设计课程里接触到了 GPT-1、GPT-2 这些早期的大语言模型。从今天的眼光看，那时的产品还很稚嫩，缺少适合普通用户的界面，主要在技术圈受到关注。但它们表现出来的语言能力，已经足够让人震撼：机器似乎不再只是按照人写好的规则处理信息，而是开始表现出理解和生成语言的能力。"
          },
          {
            "type": "html",
            "html": "<p>后来 ChatGPT 出现了。它在短时间内突破了技术圈，成为人工智能浪潮中最具标志性的产品。很多人把它的成功归因于模型能力，但我后来和当时的 OpenAI GTM 负责人 Zack Kass 交流时，得到过一个很重要的启发：GPT-3、GPT-3.5 与 ChatGPT 之间当然有能力上的进步，但真正让它破圈的，是产品重新定义了人与 AI 的交互方式。</p>",
            "text": "后来 ChatGPT 出现了。它在短时间内突破了技术圈，成为人工智能浪潮中最具标志性的产品。很多人把它的成功归因于模型能力，但我后来和当时的 OpenAI GTM 负责人 Zack Kass 交流时，得到过一个很重要的启发：GPT-3、GPT-3.5 与 ChatGPT 之间当然有能力上的进步，但真正让它破圈的，是产品重新定义了人与 AI 的交互方式。"
          },
          {
            "type": "html",
            "html": "<p>过去，模型主要通过 API 为开发者提供能力。ChatGPT 把这种能力放进了一个人人都能理解的聊天界面里。用户不用先理解 API，也不用先学会编程，只要像和人说话一样提出问题，就可以开始使用 AI。</p>",
            "text": "过去，模型主要通过 API 为开发者提供能力。ChatGPT 把这种能力放进了一个人人都能理解的聊天界面里。用户不用先理解 API，也不用先学会编程，只要像和人说话一样提出问题，就可以开始使用 AI。"
          },
          {
            "type": "html",
            "html": "<p>这件事让我越来越确信：技术本身只是起点，真正决定 AI 能否造福更多人的，是它能否进入具体的应用场景，能否降低使用门槛，能否让一个普通人把手边真实的问题交给它。</p>",
            "text": "这件事让我越来越确信：技术本身只是起点，真正决定 AI 能否造福更多人的，是它能否进入具体的应用场景，能否降低使用门槛，能否让一个普通人把手边真实的问题交给它。"
          },
          {
            "type": "html",
            "html": "<p>这也是企业 AI 转型最重要的判断之一。企业需要的不是一场技术炫技，而是让 AI 进入真实工作，帮助人解决真实问题，并逐步改变工作的组织方式。</p>",
            "text": "这也是企业 AI 转型最重要的判断之一。企业需要的不是一场技术炫技，而是让 AI 进入真实工作，帮助人解决真实问题，并逐步改变工作的组织方式。"
          },
          {
            "type": "html",
            "html": "<h2>从课程里的 AI，到硅谷现场的机会感</h2>",
            "text": "从课程里的 AI，到硅谷现场的机会感"
          },
          {
            "type": "html",
            "html": "<p>AI 快速发展的那几年，正好也是新冠疫情的几年。我们引进了 MIT 等机构的多门 AI 高管课程。疫情之后，我开始带中国企业家去硅谷进行 AI 研学。</p>",
            "text": "AI 快速发展的那几年，正好也是新冠疫情的几年。我们引进了 MIT 等机构的多门 AI 高管课程。疫情之后，我开始带中国企业家去硅谷进行 AI 研学。"
          },
          {
            "type": "html",
            "html": "<p>每一次去硅谷，都能感受到一种强烈的参与感。从大厂到创业者，从孵化器到投资人，大家讨论的几乎都是 AI。每个人都在试着判断，这场变化会创造什么机会，自己的公司应该站在哪里。</p>",
            "text": "每一次去硅谷，都能感受到一种强烈的参与感。从大厂到创业者，从孵化器到投资人，大家讨论的几乎都是 AI。每个人都在试着判断，这场变化会创造什么机会，自己的公司应该站在哪里。"
          },
          {
            "type": "html",
            "html": "<p>印象最深的一次，是参加英伟达 GTC。黄仁勋主题演讲那天，我们凌晨五点多起床，想着早点到现场，也许可以抢到靠前的位置。结果到达时，队伍已经排出去一两公里。走进体育馆，几乎座无虚席。黄仁勋穿着标志性的皮夹克，从英伟达的“武器库”里一件一件展示新的装备。</p>",
            "text": "印象最深的一次，是参加英伟达 GTC。黄仁勋主题演讲那天，我们凌晨五点多起床，想着早点到现场，也许可以抢到靠前的位置。结果到达时，队伍已经排出去一两公里。走进体育馆，几乎座无虚席。黄仁勋穿着标志性的皮夹克，从英伟达的“武器库”里一件一件展示新的装备。"
          },
          {
            "type": "html",
            "html": "<p>台上是不断加速的新技术，台下坐着从世界各地赶来的人。他们并不只是来听一场演讲，而是想弄清楚下一步的机会在哪里。</p>",
            "text": "台上是不断加速的新技术，台下坐着从世界各地赶来的人。他们并不只是来听一场演讲，而是想弄清楚下一步的机会在哪里。"
          },
          {
            "type": "html",
            "html": "<p>硅谷的交流也改变了我对创新价值的判断。硅谷人工智能研究院院长 Piero Scaruffi 曾经和我们分享过一个观点：如果你告诉投资人，你的想法可以让某个产品的性能提升 10%，通常很难引起兴趣；如果可以提升 30% 到 50%，可能会有人愿意继续听；真正让人兴奋的，是你正在创造一个过去没有人做过的生意，而且一旦做成，就可能改变一个行业。</p>",
            "text": "硅谷的交流也改变了我对创新价值的判断。硅谷人工智能研究院院长 Piero Scaruffi 曾经和我们分享过一个观点：如果你告诉投资人，你的想法可以让某个产品的性能提升 10%，通常很难引起兴趣；如果可以提升 30% 到 50%，可能会有人愿意继续听；真正让人兴奋的，是你正在创造一个过去没有人做过的生意，而且一旦做成，就可能改变一个行业。"
          },
          {
            "type": "html",
            "html": "<p>我也曾在一次有黄仁勋参加的创业活动中听到他谈“Zero-Billion Business”。它说的不是一个已经存在、正在争夺的十亿美元市场，而是一个现在还没有被定义，但一旦做成就可能达到十亿美元规模的生意。在那次活动中，他还谈到，真正值得做的是正确而困难的事情。</p>",
            "text": "我也曾在一次有黄仁勋参加的创业活动中听到他谈“Zero-Billion Business”。它说的不是一个已经存在、正在争夺的十亿美元市场，而是一个现在还没有被定义，但一旦做成就可能达到十亿美元规模的生意。在那次活动中，他还谈到，真正值得做的是正确而困难的事情。"
          },
          {
            "type": "html",
            "html": "<p>这些判断让我意识到，AI 带来的机会不能只被理解为把现有流程做得更快。更重要的问题是：当新的能力进入组织，过去不存在的工作、产品和商业模式，会不会因此出现？</p>",
            "text": "这些判断让我意识到，AI 带来的机会不能只被理解为把现有流程做得更快。更重要的问题是：当新的能力进入组织，过去不存在的工作、产品和商业模式，会不会因此出现？"
          },
          {
            "type": "html",
            "html": "<h2>先自己做，再带着别人做</h2>",
            "text": "先自己做，再带着别人做"
          },
          {
            "type": "html",
            "html": "<p>2025 年 10 月，我们创办了 MindsLeap，中文名叫心智悦动。我们的使命是：Upgrade AI Mindsets for Global Success，帮助中国企业建立 AI 时代的心智与能力，并走向更大的全球市场。</p>",
            "text": "2025 年 10 月，我们创办了 MindsLeap，中文名叫心智悦动。我们的使命是：Upgrade AI Mindsets for Global Success，帮助中国企业建立 AI 时代的心智与能力，并走向更大的全球市场。"
          },
          {
            "type": "html",
            "html": "<p>MindsLeap 这个名字里，minds 是心智，leap 是跃迁。我把中文名里的“跃”改成了“悦”，是因为很多人把变革理解成一个痛苦的过程。我想做一家让变革变得更轻快、更愉悦的公司。</p>",
            "text": "MindsLeap 这个名字里，minds 是心智，leap 是跃迁。我把中文名里的“跃”改成了“悦”，是因为很多人把变革理解成一个痛苦的过程。我想做一家让变革变得更轻快、更愉悦的公司。"
          },
          {
            "type": "html",
            "html": "<p>这家公司连接两类人：一类是拥有真实业务、客户和行业经验，却需要完成 AI 转型的传统企业家；另一类是正在探索 AI 产品和新商业模式的创业者。前者有场景，后者有能力，双方可以在同一个生态中互相赋能。</p>",
            "text": "这家公司连接两类人：一类是拥有真实业务、客户和行业经验，却需要完成 AI 转型的传统企业家；另一类是正在探索 AI 产品和新商业模式的创业者。前者有场景，后者有能力，双方可以在同一个生态中互相赋能。"
          },
          {
            "type": "html",
            "html": "<p>既然我们要打造一个 AI 原生企业的产业加速平台，就应该从创业第一天开始，先把自己的公司实践一遍。只要发现一个新的工作场景，我们就尝试用 AI 做一遍。</p>",
            "text": "既然我们要打造一个 AI 原生企业的产业加速平台，就应该从创业第一天开始，先把自己的公司实践一遍。只要发现一个新的工作场景，我们就尝试用 AI 做一遍。"
          },
          {
            "type": "html",
            "html": "<p>官网第一版就是这样上线的：从想法到可用版本，只花了一天。后来，内容中心、视频中心、GEO 优化、网站维护、产品设计、活动策划、财务和合规，都逐步变成了人和 Agent 共同完成的工作。</p>",
            "text": "官网第一版就是这样上线的：从想法到可用版本，只花了一天。后来，内容中心、视频中心、GEO 优化、网站维护、产品设计、活动策划、财务和合规，都逐步变成了人和 Agent 共同完成的工作。"
          },
          {
            "type": "html",
            "html": "<p>今天，MindsLeap 有 4 位团队成员和一组持续协作的智能体。市场职能没有单独招聘市场部员工，网站、内容、视频和 GEO 都由团队成员编排 Agent 完成；财务和合规有 Agent 辅助；产品设计由人和 AI 深度协作；活动从策划、视觉、报名系统到现场材料，也由人和 Agent 共同推进。</p>",
            "text": "今天，MindsLeap 有 4 位团队成员和一组持续协作的智能体。市场职能没有单独招聘市场部员工，网站、内容、视频和 GEO 都由团队成员编排 Agent 完成；财务和合规有 Agent 辅助；产品设计由人和 AI 深度协作；活动从策划、视觉、报名系统到现场材料，也由人和 Agent 共同推进。"
          },
          {
            "type": "html",
            "html": "<p>这套分工不是提前画在组织图上的。往往是我们在一次交付里发现，有一步人可以放手，又有一步原本以为可以交出去，最后还是得自己把关。</p>",
            "text": "这套分工不是提前画在组织图上的。往往是我们在一次交付里发现，有一步人可以放手，又有一步原本以为可以交出去，最后还是得自己把关。"
          },
          {
            "type": "html",
            "html": "<p>MindsLeap 的这段经历让我看到，AI 原生组织不是给传统公司增加一个 AI 部门，也不是把几个工具放到原有流程旁边。它需要重新思考：哪些工作由人完成，哪些工作交给 Agent；人如何表达目标和上下文；组织如何给 Agent 权限；经验如何沉淀为 Skill、Workflow 和 Memory；最终又如何把这些能力转化为客户价值和经营结果。</p>",
            "text": "MindsLeap 的这段经历让我看到，AI 原生组织不是给传统公司增加一个 AI 部门，也不是把几个工具放到原有流程旁边。它需要重新思考：哪些工作由人完成，哪些工作交给 Agent；人如何表达目标和上下文；组织如何给 Agent 权限；经验如何沉淀为 Skill、Workflow 和 Memory；最终又如何把这些能力转化为客户价值和经营结果。"
          },
          {
            "type": "html",
            "html": "<h2>AI 原生浪潮才刚刚开始</h2>",
            "text": "AI 原生浪潮才刚刚开始"
          },
          {
            "type": "html",
            "html": "<p>2026 年 5 月 23 日的 AI 原生企业大会，是 MindsLeap 的一个重要节点。我们把来自硅谷的前沿观察、自己公司的实践和传统企业的转型问题，放到同一个场域里讨论。近 300 位企业家、投资人与科创专家参加了大会，上海多个区的相关领导到场交流，Steve Hoffman 带来了两场主旨演讲。</p>",
            "text": "2026 年 5 月 23 日的 AI 原生企业大会，是 MindsLeap 的一个重要节点。我们把来自硅谷的前沿观察、自己公司的实践和传统企业的转型问题，放到同一个场域里讨论。近 300 位企业家、投资人与科创专家参加了大会，上海多个区的相关领导到场交流，Steve Hoffman 带来了两场主旨演讲。"
          },
          {
            "type": "html",
            "html": "<p>同年 8 月，我受德勤中国区董事会主席和 CEO 邀请，在德勤中国管理团队会议上分享如何打造 AI 原生组织；我也受重庆市政府邀请，参加 OPC 三创大会并作主题分享，受南昌工商联邀请，为 50 位企业家分享 AI 原生组织与 AI 营销团队的构建方法，并为中欧商学院市场部培训如何构建 AI 营销团队。</p>",
            "text": "同年 8 月，我受德勤中国区董事会主席和 CEO 邀请，在德勤中国管理团队会议上分享如何打造 AI 原生组织；我也受重庆市政府邀请，参加 OPC 三创大会并作主题分享，受南昌工商联邀请，为 50 位企业家分享 AI 原生组织与 AI 营销团队的构建方法，并为中欧商学院市场部培训如何构建 AI 营销团队。"
          },
          {
            "type": "html",
            "html": "<p>这些不同场景中的人，问的其实是同一个问题：当 AI 开始承担越来越多的执行工作，人应该做什么，原有的分工、协作和管理方式又该如何调整？</p>",
            "text": "这些不同场景中的人，问的其实是同一个问题：当 AI 开始承担越来越多的执行工作，人应该做什么，原有的分工、协作和管理方式又该如何调整？"
          },
          {
            "type": "html",
            "html": "<p>AI 原生对很多企业来说，是一个很高的目标，也是一条正在逐渐清晰的方向。它不会因为某个工具发布，或某个模型升级，就在某一天自动完成。它需要从一个真实场景开始，在一次次交付中形成反馈，再把经过验证的经验沉淀为组织能力。</p>",
            "text": "AI 原生对很多企业来说，是一个很高的目标，也是一条正在逐渐清晰的方向。它不会因为某个工具发布，或某个模型升级，就在某一天自动完成。它需要从一个真实场景开始，在一次次交付中形成反馈，再把经过验证的经验沉淀为组织能力。"
          },
          {
            "type": "html",
            "html": "<p>我想做的，是探索出一套适合中国企业的 AI 原生组织方法：把管理学中仍然有效的部分保留下来，把 AI 带来的新变量放进去，在实践中重新理解人、工作、结构与文化之间的关系。</p>",
            "text": "我想做的，是探索出一套适合中国企业的 AI 原生组织方法：把管理学中仍然有效的部分保留下来，把 AI 带来的新变量放进去，在实践中重新理解人、工作、结构与文化之间的关系。"
          },
          {
            "type": "html",
            "html": "<p>这本书，就是这段探索的记录。</p>",
            "text": "这本书，就是这段探索的记录。"
          },
          {
            "type": "html",
            "html": "<h2>岸上和水里</h2>",
            "text": "岸上和水里"
          },
          {
            "type": "html",
            "html": "<p>写《海啸之后》的时候，我更多从社会和人的尺度思考 AI。那是我以线上形式发布的第一本电子书，讨论工作如何变化，人的身份建立在什么之上，超级组织和超级个体如何共存，以及我们最终想成为什么样的人。</p>",
            "text": "写《海啸之后》的时候，我更多从社会和人的尺度思考 AI。那是我以线上形式发布的第一本电子书，讨论工作如何变化，人的身份建立在什么之上，超级组织和超级个体如何共存，以及我们最终想成为什么样的人。"
          },
          {
            "type": "html",
            "html": "<p>但那本书写完以后，一个问题一直跟着我：海啸来了，一个企业家星期一早上到公司，究竟应该做什么？</p>",
            "text": "但那本书写完以后，一个问题一直跟着我：海啸来了，一个企业家星期一早上到公司，究竟应该做什么？"
          },
          {
            "type": "html",
            "html": "<p>《海啸之后》是站在岸上看浪。这一本书，要下到水里。</p>",
            "text": "《海啸之后》是站在岸上看浪。这一本书，要下到水里。"
          },
          {
            "type": "html",
            "html": "<p>如果说前一本书关注十年之后的世界，这一本关注下一个季度的公司；前一本书追问“我们想成为什么”，这一本书追问“我的公司从哪里开始”。</p>",
            "text": "如果说前一本书关注十年之后的世界，这一本关注下一个季度的公司；前一本书追问“我们想成为什么”，这一本书追问“我的公司从哪里开始”。"
          },
          {
            "type": "html",
            "html": "<p>本书主要写给中国中小企业的创始人和管理团队。这类企业的决策链条较短，创始人能够直接参与资源、流程和人员调整，更有机会从一个具体问题出发，看到新的工作方式如何改变经营结果。大型企业也可以从新事业部、新业务线或相对独立的团队开始，让一种新的组织方式先跑起来，再把验证过的经验带回更大的体系。</p>",
            "text": "本书主要写给中国中小企业的创始人和管理团队。这类企业的决策链条较短，创始人能够直接参与资源、流程和人员调整，更有机会从一个具体问题出发，看到新的工作方式如何改变经营结果。大型企业也可以从新事业部、新业务线或相对独立的团队开始，让一种新的组织方式先跑起来，再把验证过的经验带回更大的体系。"
          },
          {
            "type": "html",
            "html": "<p>接下来的章节会从 AI 带来的变化开始，讨论传统企业欠下的认知债、技术债和组织债，再进入数据、People 与 Agents、工作流、结构、文化、灯塔项目、Private Evals、FDE 和风险治理。</p>",
            "text": "接下来的章节会从 AI 带来的变化开始，讨论传统企业欠下的认知债、技术债和组织债，再进入数据、People 与 Agents、工作流、结构、文化、灯塔项目、Private Evals、FDE 和风险治理。"
          },
          {
            "type": "html",
            "html": "<p>这本书也有 AI 的深度参与。它帮助我整理演讲和访谈，检索资料，讨论结构，并参与文字的反复修改。但清楚的文字和清楚的理解之间仍有距离：这是不是我的意思，这个结论有没有超出实践能够支持的范围，这些判断只能由我自己完成。</p>",
            "text": "这本书也有 AI 的深度参与。它帮助我整理演讲和访谈，检索资料，讨论结构，并参与文字的反复修改。但清楚的文字和清楚的理解之间仍有距离：这是不是我的意思，这个结论有没有超出实践能够支持的范围，这些判断只能由我自己完成。"
          },
          {
            "type": "html",
            "html": "<p>企业的 AI 转型也是如此。创始人可以请顾问，可以购买系统，也可以让团队负责实施，但什么值得改变、哪些代价可以接受、企业希望长出什么能力，仍然需要创始人亲自参与。</p>",
            "text": "企业的 AI 转型也是如此。创始人可以请顾问，可以购买系统，也可以让团队负责实施，但什么值得改变、哪些代价可以接受、企业希望长出什么能力，仍然需要创始人亲自参与。"
          },
          {
            "type": "html",
            "html": "<p class=\"pullquote\"><strong>理解不能外包。</strong></p>",
            "text": "理解不能外包。"
          },
          {
            "type": "html",
            "html": "<p>岸上学不会游泳。</p>",
            "text": "岸上学不会游泳。"
          },
          {
            "type": "html",
            "html": "<p>这本书不是我站在岸上教你，而是我一边建公司、一边走进别人的公司、一边把实践写下来。我想邀请你做的，是先跳下水，亲手用 AI 做成一件真实的事，亲手带一个 AI 员工，让自己获得使用 AI 和管理 Agent 的体感。</p>",
            "text": "这本书不是我站在岸上教你，而是我一边建公司、一边走进别人的公司、一边把实践写下来。我想邀请你做的，是先跳下水，亲手用 AI 做成一件真实的事，亲手带一个 AI 员工，让自己获得使用 AI 和管理 Agent 的体感。"
          },
          {
            "type": "html",
            "html": "<p>方向可以在实践中校准，体感只能自己获得。</p>",
            "text": "方向可以在实践中校准，体感只能自己获得。"
          },
          {
            "type": "html",
            "html": "<p>但在开始之前，先回答一个我在企业家访谈中经常遇到的问题：为什么很多企业家已经关注 AI、讨论 AI、每天使用 AI，公司却一直没有真正改变？</p>",
            "text": "但在开始之前，先回答一个我在企业家访谈中经常遇到的问题：为什么很多企业家已经关注 AI、讨论 AI、每天使用 AI，公司却一直没有真正改变？"
          },
          {
            "type": "html",
            "html": "<hr/>",
            "text": ""
          },
          {
            "type": "html",
            "html": "<h3>序章尾注</h3>",
            "text": "序章尾注"
          },
          {
            "type": "html",
            "html": "<ol class=\"notes\">\n<li>AI 原生企业大会：2026 年 5 月 23 日，上海虹桥 REMIXX 国际艺术中心，MindsLeap 为联合主办方之一。参会人数按主办方统计为近 300 位。大会筹备期团队为 3 人，书稿写作时团队为 4 人；活动策划、视觉、报名系统、现场音乐与演示文稿等工作由团队成员与 AI Agent 协同完成。</li>\n<li>Emeritus 是一家教育科技独角兽，与全球多所顶尖大学及商学院合作提供高管教育课程。作者任中国区 COO 期间，参与运营沃顿、哥伦比亚大学、MIT 等机构的相关课程；具体课程名称与院校名单出版前核对。</li>\n<li>GTC 场景来自作者带企业家团参加英伟达 GTC 的亲历。Steve Hoffman 是 Founders Space 创始人，作者任 Founders Space 合伙人兼中国区 CEO。Pieter Abbeel、Piero Scaruffi、Zack Kass 等人物和职务表述，出版前根据正式资料核对。</li>\n<li>德勤中国分享为受邀交流，不构成德勤对本书的背书；重庆 OPC 三创大会和南昌工商联活动的主办方、日期及职务表述，出版前根据正式活动资料核对。</li>\n<li>本章关于 MindsLeap 团队和 AI Agent 的描述，基于作者对公司当前工作方式的介绍。Agent 参与工作不等于所有任务都由 Agent 独立完成，涉及重要业务节点仍由人负责判断、审核与承担责任。</li>\n<li>《海啸之后》为作者与 AI 共同推演写成的电子书，以线上形式发布，截至本书写作时尚未纸质出版。</li>\n</ol>",
            "text": "\nAI 原生企业大会：2026 年 5 月 23 日，上海虹桥 REMIXX 国际艺术中心，MindsLeap 为联合主办方之一。参会人数按主办方统计为近 300 位。大会筹备期团队为 3 人，书稿写作时团队为 4 人；活动策划、视觉、报名系统、现场音乐与演示文稿等工作由团队成员与 AI Agent 协同完成。\nEmeritus 是一家教育科技独角兽，与全球多所顶尖大学及商学院合作提供高管教育课程。作者任中国区 COO 期间，参与运营沃顿、哥伦比亚大学、MIT 等机构的相关课程；具体课程名称与院校名单出版前核对。\nGTC 场景来自作者带企业家团参加英伟达 GTC 的亲历。Steve Hoffman 是 Founders Space 创始人，作者任 Founders Space 合伙人兼中国区 CEO。Pieter Abbeel、Piero Scaruffi、Zack Kass 等人物和职务表述，出版前根据正式资料核对。\n德勤中国分享为受邀交流，不构成德勤对本书的背书；重庆 OPC 三创大会和南昌工商联活动的主办方、日期及职务表述，出版前根据正式活动资料核对。\n本章关于 MindsLeap 团队和 AI Agent 的描述，基于作者对公司当前工作方式的介绍。Agent 参与工作不等于所有任务都由 Agent 独立完成，涉及重要业务节点仍由人负责判断、审核与承担责任。\n《海啸之后》为作者与 AI 共同推演写成的电子书，以线上形式发布，截至本书写作时尚未纸质出版。\n"
          }
