            "html": "<ol class=\"notes\"><li>Founders Talk 为作者发起的访谈节目。卫瓴科技春节实验，出自作者与卫瓴科技 CEO 杨炯纬在该节目中的对话（2026 年 3 月录制，4 月发布）。三只\"龙虾\"的分工、35 天 500 多篇、健康度下降 50 分、三类问题、接入监测 API 与 Google Search Console 后的 9 次进化，均为杨炯纬在对话中的陈述；引用出版前征得本人同意。\"龙虾\"为社区对 OpenClaw 类本地 AI 员工的叫法。</li><li>\"AI 员工最大的风险不是懒\"与\"没有反馈闭环，AI 只是一个自动化工具\"，为作者在该次对话后形成的判断。</li><li>人在环中的四个节点（目标、信息冲突、可逆性、责任），为作者提出的判断标准。</li><li>Hoffman \"你是系统的架构师，而不是任务的操作者\"及\"先从后台部署，保持人在回路\"，均出自其 2026 年 5 月 23 日 AI 原生企业大会主旨演讲。杨炯纬\"我能给所有员工看的，我就能给龙虾看\"出自注 1 的同一次对话。</li><li>Loop Engineering 为 2026 年夏天起在硅谷 AI 圈流行的提法，作者在 2026 年 8 月口播视频《AI 应用的差距是缩小了还是拉大了》中曾用它解释系统级能力；\"五件事\"的拆法为作者的表述。出处与最早使用者出版前核对。</li><li>Klarna 第一幕数据（相当于 700 名全职客服、11 分钟到 2 分钟）为 Klarna 2024 年自行公布，未经独立审计；第二幕为 2025 年 5 月其 CEO Sebastian Siemiatkowski 的公开表态。出版前补查并链接原始报道。作者在《海啸之后》中引用过第一幕。</li><li>ContentHub、VideoHub 为 MindsLeap 内部的内容与视频工作流，此处描述为作者的一手实践；接入播放量等真实数据的反馈闭环截至本章写作时仍为计划。</li></ol>",
