            "html": "<p>我在沃顿商学院的管理发展课程里，接触过一个组织管理领域非常重要的模型：Nadler-Tushman 一致性模型。</p>",
            "text": "我在沃顿商学院的管理发展课程里，接触过一个组织管理领域非常重要的模型：Nadler-Tushman 一致性模型。"
