            "html": "<p>Digital Lincoln 就是让它认识我的那套东西。它不是聊天机器人，也不是知识库。我过去的文章、演讲、书稿、录音、真实的项目材料和经历，被提炼成一张一张的记忆卡——我的经历、我的观点、我的身份、我的价值观、我认识的人——每张卡带着来源、时间和确认状态。现在它不只帮我写稿，还帮我管理重要的信息，管理我认识的所有人，管理我参与的每一个真实项目。</p>",
            "text": "Digital Lincoln 就是让它认识我的那套东西。它不是聊天机器人，也不是知识库。我过去的文章、演讲、书稿、录音、真实的项目材料和经历，被提炼成一张一张的记忆卡——我的经历、我的观点、我的身份、我的价值观、我认识的人——每张卡带着来源、时间和确认状态。现在它不只帮我写稿，还帮我管理重要的信息，管理我认识的所有人，管理我参与的每一个真实项目。"
