            "text": "员工有权看，不等于替他办事的 Agent 就该全看。准备一次客户会议，可能只需要这家客户的订单和已批准的产品资料，不需要整个销售团队的合同。人的权限是上限，任务决定实际开放多少；能查也不等于能改。"
