            "text": "\nDigital Lincoln 的建立、记忆分类及来源与确认机制，依据作者的一手实践与 2026 年 8 月的视频《每个人都应该做一个第二大脑》。\n\"AI 战略的第一步是数据战略\"为作者在 Emeritus 任职期间学习 MIT 相关课程的记忆；课程名称与讲师出版前核对。\n\"收入\"的四种含义与\"客户\"的三种定义为作者在企业诊断中常见情形的概括，不对应具体客户。\nPalantir 的 Ontology 为该公司企业软件的核心概念；\"数据、逻辑、行为、安全\"四层与\"以决策为中心的系统\"为作者对相关框架的概括，用于本书的教学表述，不是 Palantir 的官方分层。出版前核对 Palantir 公开文档中的表述。\n房地产项目公司诊断报告中数据底座的三条原则（围绕决策对象建表、先轻后重、先样本后平台），按报告概括；客户信息已隐去。\n"
