            "html": "<p>今年 9 月我做过一期视频，讲吴恩达谈的一个词：cognitive offloading，认知卸载。把思考交给 AI，人负责确认。我在那期里坦白，我也会这样——AI 给出一个看起来合理的回答，我就说\"大差不差，你继续\"。</p>",
            "text": "今年 9 月我做过一期视频，讲吴恩达谈的一个词：cognitive offloading，认知卸载。把思考交给 AI，人负责确认。我在那期里坦白，我也会这样——AI 给出一个看起来合理的回答，我就说\"大差不差，你继续\"。"
