          {
            "type": "html",
            "html": "<h3 class=\"notes-title\">尾注</h3>",
            "text": "尾注"
          },
          {
            "type": "html",
            "html": "<ol class=\"notes\"><li>\"大差不差，你继续吧\"为作者自述的使用习惯，出自作者 2026 年 9 月 5 日视频；吴恩达关于认知卸载（cognitive offloading）的讨论为作者在该口播视频中的转述，原访谈出处出版前核对。</li><li>七类风险的排列为作者的整理；\"Shadow AI\"为业界通用说法。</li><li>单向门与双向门的区分，出自亚马逊的决策原则，作者在视频中转述。</li><li>杨炯纬的\"特洛伊木马\"比喻与四条安全原则，出自作者与其在 Founders Talk 节目中的对话（2026 年 3 月录制）；引用出版前征得本人同意。</li><li>\"让多模型、多 Agent 互评协作\"为作者在 2026 年 4 月 AI 龙虾上海站的分享中提出。</li><li>\"确认者\"的风险与\"判断力是需要练习的\"，见作者《海啸之后》第十章；\"先独立判断、比较、追问遗漏\"三条为作者在 2026 年 9 月口播视频中的自述做法。</li><li>六类必须有人确认的事项与四个名字，为作者给企业的建议框架。法规部分不构成法律意见，出版前请专业人士审校。</li></ol>",
            "text": "\"大差不差，你继续吧\"为作者自述的使用习惯，出自作者 2026 年 9 月 5 日视频；吴恩达关于认知卸载（cognitive offloading）的讨论为作者在该口播视频中的转述，原访谈出处出版前核对。七类风险的排列为作者的整理；\"Shadow AI\"为业界通用说法。单向门与双向门的区分，出自亚马逊的决策原则，作者在视频中转述。杨炯纬的\"特洛伊木马\"比喻与四条安全原则，出自作者与其在 Founders Talk 节目中的对话（2026 年 3 月录制）；引用出版前征得本人同意。\"让多模型、多 Agent 互评协作\"为作者在 2026 年 4 月 AI 龙虾上海站的分享中提出。\"确认者\"的风险与\"判断力是需要练习的\"，见作者《海啸之后》第十章；\"先独立判断、比较、追问遗漏\"三条为作者在 2026 年 9 月口播视频中的自述做法。六类必须有人确认的事项与四个名字，为作者给企业的建议框架。法规部分不构成法律意见，出版前请专业人士审校。"
          }
